/**
 * Every subscription whose workspace still exists. Archived (deleted)
 * workspaces are omitted — billing jobs must not touch them.
 */
export async function listLiveSubscriptions(): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

export type SubscriptionPatch = {
  plan?: PlanId;
  interval?: BillingInterval;
  status?: SubscriptionStatus;
  seats?: number;
  currentPeriodStart?: IsoTimestamp;
  currentPeriodEnd?: IsoTimestamp;
  cancelAt?: IsoTimestamp | null;
};

/** Partial write used by renewal and by a free-to-paid period reset. */
export async function updateSubscription(
  orgId: OrgId,
  patch: SubscriptionPatch,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

