/**
 * Moves one live subscription forward as of `now`.
 *
 * Returns how many periods were opened, or 1 when a cancellation took effect.
 * A second call at the same instant returns 0.
 */
export async function advanceSubscription(
  subscription: Subscription,
  now: Date,
): Promise<number> {
  if (
    subscription.status === "trialing" ||
    subscription.status === "past_due"
  ) {
    return 0;
  }

  if (subscription.status === "canceled") {
    if (
      subscription.cancelAt === null ||
      parseIso(subscription.cancelAt).getTime() > now.getTime()
    ) {
      return 0;
    }
    await finalizeCancellation(subscription, now);
    return 1;
  }

  if (subscription.status !== "active") return 0;

  let periodStart = parseIso(subscription.currentPeriodStart);
  let periodEnd = parseIso(subscription.currentPeriodEnd);
  if (periodEnd.getTime() > now.getTime()) return 0;

  let opened = 0;
  while (periodEnd.getTime() <= now.getTime()) {
    const nextStart = periodEnd;
    const nextEnd = addBillingInterval(nextStart, subscription.interval);
    if (nextEnd.getTime() <= nextStart.getTime()) break;

    if (isPaidPlan(subscription.plan)) {
      await issueInvoice({
        orgId: subscription.orgId,
        amountCents: fullPeriodChargeCents(
          subscription.plan,
          subscription.seats,
          subscription.interval,
        ),
        periodStart: toIsoTimestamp(nextStart),
        periodEnd: toIsoTimestamp(nextEnd),
        actorId: null,
        occurredAt: now,
      });
    }

    periodStart = nextStart;
    periodEnd = nextEnd;
    opened += 1;

    await subscriptionRepo.updateSubscription(subscription.orgId, {
      currentPeriodStart: toIsoTimestamp(periodStart),
      currentPeriodEnd: toIsoTimestamp(periodEnd),
    });
  }

  return opened;
}

/** Anniversary billing: same clock time, clamping short months forward. */
export function addBillingInterval(
  start: Date,
  interval: BillingInterval,
): Date {
  const months = monthsInInterval(interval);
  const monthIndex = start.getUTCMonth() + months;
  const targetYear = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const targetMonth = monthIndex % 12;
  const lastDay = new Date(
    Date.UTC(targetYear, targetMonth + 1, 0),
  ).getUTCDate();
  const targetDay = Math.min(start.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      targetYear,
      targetMonth,
      targetDay,
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** Whole days in the period, rounded, and never zero. */
export function daysInPeriod(start: Date, end: Date): number {
  return Math.max(1, Math.round((end.getTime() - start.getTime()) / DAY_MS));
}

/**
 * Whole or started days from `at` until `end`. None once `end` has been
 * reached, so 14 days and 22 hours counts as 15.
 */
export function daysRemaining(at: Date, end: Date): number {
  const remaining = end.getTime() - at.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / DAY_MS);
}

/** Full-period amount scaled by days left, rounded down to cents. */
export function prorateCents(
  fullAmountCents: number,
  at: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  if (fullAmountCents <= 0) return 0;
  const left = daysRemaining(at, periodEnd);
  if (left === 0) return 0;
  return Math.floor(
    (fullAmountCents * left) / daysInPeriod(periodStart, periodEnd),
  );
}

export function fullPeriodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

function isPaidPlan(plan: PlanId): boolean {
  return getPlanLimits(plan).priceCentsPerSeatMonthly > 0;
}

type IssueInvoiceInput = {
  orgId: OrgId;
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
  actorId: UserId | null;
  occurredAt: Date;
};

/**
 * Persists one invoice and announces it once: domain event, audit row, and
 * a single notification to the workspace owner. Zero cents is not an invoice.
 */
export async function issueInvoice(
  input: IssueInvoiceInput,
): Promise<Invoice | null> {
  if (input.amountCents <= 0) return null;

  const existing = await invoiceRepo.listInvoices(input.orgId);
  const used = new Set(existing.map((invoice) => invoice.number));
  let sequence = existing.length + 1;
  let number = invoiceNumber(sequence);
  while (used.has(number)) {
    sequence += 1;
    number = invoiceNumber(sequence);
  }

  const invoice = await invoiceRepo.insertInvoice(input.orgId, {
    orgId: input.orgId,
    number,
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  const occurredAt = toIsoTimestamp(input.occurredAt);

  await emit("billing.invoice_issued", {
    orgId: input.orgId,
    actorId: input.actorId,
    occurredAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  await record(input.orgId, "billing.invoice_issued", {
    actorId: input.actorId,
    subjectKind: "subscription",
    subjectId: input.orgId,
    projectId: null,
    summary: `Issued invoice ${invoice.number}`,
    metadata: {
      invoiceId: invoice.id,
      invoiceNumber: invoice.number,
      amountCents: invoice.amountCents,
    },
  });

  const org = await orgRepo.findOrgById(input.orgId);
  if (org && org.archivedAt === null) {
    await notify(
      input.orgId,
      "invoice_issued",
      [org.ownerId],
      {
        title: `Invoice ${invoice.number}`,
        body: `${formatCents(invoice.amountCents, "USD")} due on invoice ${invoice.number}.`,
        href: `/${org.slug}/settings/billing`,
        // The owner is told even when they made the change themselves.
        actorId: null,
      },
    );
  }

  return invoice;
}

function invoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(4, "0")}`;
}

/** Ends a canceled subscription on the free plan as of its cancellation date. */
async function finalizeCancellation(
  subscription: Subscription,
  now: Date,
): Promise<void> {
  let start = parseIso(subscription.cancelAt ?? toIsoTimestamp(now));
  let end = addBillingInterval(start, "monthly");

  while (end.getTime() <= now.getTime()) {
    const nextEnd = addBillingInterval(end, "monthly");
    if (nextEnd.getTime() <= end.getTime()) break;
    start = end;
    end = nextEnd;
  }

  await subscriptionRepo.updateSubscription(subscription.orgId, {
    plan: "free",
    interval: "monthly",
    status: "active",
    cancelAt: null,
    currentPeriodStart: toIsoTimestamp(start),
    currentPeriodEnd: toIsoTimestamp(end),
  });
  await orgRepo.updateOrgPlan(subscription.orgId, "free");

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(now),
    from: subscription.plan,
    to: "free",
  });
}

