/**
 * Renews subscriptions whose period has ended and finalizes cancellations.
 *
 * One new period is opened per elapsed interval. Paid periods are invoiced in
 * full; the free plan moves forward without an invoice. A canceled
 * subscription stays put until its cancellation date, then becomes the free
 * plan. Trialing and past-due subscriptions are left for the trial-expiry job.
 *
 * Must call (do not reimplement): advanceSubscription
 */
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { advanceSubscription } from "@/server/services/billing-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const logger = createLogger("billing-renewal-job");

/**
 * Sweeps every live workspace. Running again at the same `now` is a no-op:
 * periods already lie past `now`, and a cancellation already applied is an
 * active free subscription.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listLiveSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const opened = await advanceSubscription(subscription, now);
        result.processed += opened;

        if (opened > 0) {
          logger.debug("subscription advanced", {
            orgId: subscription.orgId,
            opened,
            at: now.toISOString(),
          });
        }
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

