import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import { changePlan, updateSeats } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("period arithmetic", () => {
  it("clamps short months and carries the clamped day forward", () => {
    const jan31 = new Date("2026-01-31T15:04:05.000Z");
    const feb = addBillingInterval(jan31, "monthly");
    expect(feb.toISOString()).toBe("2026-02-28T15:04:05.000Z");
    const march = addBillingInterval(feb, "monthly");
    expect(march.toISOString()).toBe("2026-03-28T15:04:05.000Z");

    const leap = new Date("2024-02-29T00:00:00.000Z");
    expect(addBillingInterval(leap, "annual").toISOString()).toBe(
      "2025-02-28T00:00:00.000Z",
    );
  });

  it("counts a started day and prorates down to cents", () => {
    const start = new Date("2026-01-01T00:00:00.000Z");
    const end = new Date("2026-02-01T00:00:00.000Z");
    const at = new Date("2026-01-17T02:00:00.000Z");
    expect(daysRemaining(at, end)).toBe(15);
    expect(prorateCents(1800, at, start, end)).toBe(870);
    expect(prorateCents(1800, end, start, end)).toBe(0);
  });
});

