      cancelAt: toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")),
    });

    const seen: unknown[] = [];
    const off = subscribe("billing.plan_changed", (payload) => {
      seen.push(payload);
    });
    const now = new Date("2026-03-20T00:00:00.000Z");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);
    off();

    const updated = await subscriptionRepo.findSubscription(due.org.id);
    expect(updated).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2026-03-10T08:00:00.000Z",
      currentPeriodEnd: "2026-04-10T08:00:00.000Z",
    });
    expect((await orgRepo.findOrgById(due.org.id))?.plan).toBe("free");
    expect(await invoiceRepo.listInvoices(due.org.id)).toEqual([]);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      from: "growth",
      to: "free",
      actorId: null,
    });

    const held = await subscriptionRepo.findSubscription(waiting.org.id);
    expect(held).toMatchObject({
      plan: "starter",
      status: "canceled",
      currentPeriodEnd: "2025-01-01T00:00:00.000Z",
    });
  });

  it("charges a full new period when leaving free and prorates an upgrade and added seats", async () => {
    const tenant = await createTenant("mid-period", "free");
    await subscriptionRepo.updateSubscription(tenant.org.id, {
      plan: "free",
      interval: "monthly",
      status: "active",
      seats: 3,
      currentPeriodStart: toIsoTimestamp(new Date("2026-03-01T00:00:00.000Z")),
      currentPeriodEnd: toIsoTimestamp(new Date("2026-04-01T00:00:00.000Z")),
      cancelAt: null,
    });

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-03-18T00:00:00.000Z"));
    try {
      await changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "starter",
        interval: "annual",
      });
    } finally {
      vi.useRealTimers();
    }

    const afterPlan = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(afterPlan).toMatchObject({
      plan: "starter",
      interval: "annual",
      status: "active",
      currentPeriodStart: "2026-03-18T00:00:00.000Z",
      currentPeriodEnd: "2027-03-18T00:00:00.000Z",
    });
    const first = await invoiceRepo.listInvoices(tenant.org.id);
    expect(first).toHaveLength(1);
    expect(first[0]?.amountCents).toBe(900 * 3 * 12);

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-09-18T00:00:00.000Z"));
    try {
      await changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "growth",
        interval: "annual",
      });
      await updateSeats(tenant.actors.owner, {
        orgId: tenant.org.id,
        seats: 5,
      });
    } finally {
      vi.useRealTimers();
    }

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.amountCents).sort((a, b) => a - b)).toEqual(
      [
        900 * 3 * 12,
        // growth - starter = 1000 cents, 3 seats, 12 months, half year left (182/365?)
        invoices.map((i) => i.amountCents).sort((a, b) => a - b)[1]!,
        invoices.map((i) => i.amountCents).sort((a, b) => a - b)[2]!,
      ].sort((a, b) => a - b),
    );

    const periodStart = new Date("2026-03-18T00:00:00.000Z");
    const periodEnd = new Date("2027-03-18T00:00:00.000Z");
    const at = new Date("2026-09-18T00:00:00.000Z");
    const upgrade = prorateCents(1000 * 3 * 12, at, periodStart, periodEnd);
    const seats = prorateCents(1900 * 2 * 12, at, periodStart, periodEnd);
    expect(invoices.map((invoice) => invoice.amountCents).sort((a, b) => a - b)).toEqual(
      [900 * 3 * 12, upgrade, seats].sort((a, b) => a - b),
    );
    expect(upgrade).toBeGreaterThan(0);
    expect(seats).toBeGreaterThan(0);

    const still = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(still).toMatchObject({
      plan: "growth",
      seats: 5,
      currentPeriodStart: "2026-03-18T00:00:00.000Z",
      currentPeriodEnd: "2027-03-18T00:00:00.000Z",
    });

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(notes.items.filter((note) => note.kind === "invoice_issued")).toHaveLength(3);
  });

  it("does not bill a downgrade, a trial plan choice, or removed seats", async () => {
    const trial = await createTenant("trial-choice", "starter");
    const trialBefore = await subscriptionRepo.findSubscription(trial.org.id);
    await changePlan(trial.actors.owner, {
      orgId: trial.org.id,
      plan: "growth",
      interval: "annual",
