    await changePlan(active.actors.owner, {
      orgId: active.org.id,
      plan: "starter",
      interval: "monthly",
    });
    await updateSeats(active.actors.owner, {
      orgId: active.org.id,
      seats: 2,
    });
    expect(await invoiceRepo.listInvoices(active.org.id)).toEqual([]);
    const after = await subscriptionRepo.findSubscription(active.org.id);
    expect(after).toMatchObject({
      plan: "starter",
      seats: 2,
      currentPeriodEnd: "2026-04-01T00:00:00.000Z",
    });
  });
});
